CREATE TABLE one_time_incomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, title text NOT NULL, amount numeric(14,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'CZK', date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX one_time_incomes_owner_idx ON one_time_incomes (owner_id, date);
